import requests

def test_get_health_returns_healthy_status():
    url = "http://127.0.0.1:8000/health"
    headers = {
        "Accept": "application/json"
    }
    try:
        response = requests.get(url, headers=headers, timeout=30)
        response.raise_for_status()
    except requests.RequestException as e:
        assert False, f"Request to /health failed: {e}"

    assert response.status_code == 200, f"Expected status code 200, got {response.status_code}"
    try:
        data = response.json()
    except ValueError:
        assert False, "Response is not valid JSON"

    assert "status" in data, "Response JSON does not contain 'status' key"
    assert data["status"] == "healthy", f"Expected status 'healthy', got '{data['status']}'"

test_get_health_returns_healthy_status()

import requests

def test_post_auth_login_returns_access_token_for_valid_credentials():
    base_url = "http://127.0.0.1:8000"
    login_url = f"{base_url}/api/v1/auth/login"
    headers = {
        "Content-Type": "application/json"
    }
    payload = {
        "email": "dev@example.com",
        "password": "password"
    }
    try:
        response = requests.post(login_url, json=payload, headers=headers, timeout=30)
        assert response.status_code == 200, f"Expected status code 200, got {response.status_code}"
        json_response = response.json()
        assert "access_token" in json_response, "Response JSON missing 'access_token'"
        assert "token_type" in json_response, "Response JSON missing 'token_type'"
        assert json_response["token_type"].lower() == "bearer", f"Expected token_type 'bearer', got {json_response['token_type']}"
    except requests.RequestException as e:
        assert False, f"Request to {login_url} failed: {e}"

test_post_auth_login_returns_access_token_for_valid_credentials()

import requests

BASE_URL = "http://127.0.0.1:8000"
TIMEOUT = 30

def test_post_graphql_returns_valid_graphql_response():
    url = f"{BASE_URL}/graphql"
    introspection_query = {
        "query": """
        query IntrospectionQuery {
          __schema {
            queryType { name }
            mutationType { name }
            subscriptionType { name }
            types {
              ...FullType
            }
            directives {
              name
              description
              locations
              args {
                ...InputValue
              }
            }
          }
        }
        fragment FullType on __Type {
          kind
          name
          description
          fields(includeDeprecated: true) {
            name
            description
            args {
              ...InputValue
            }
            type {
              ...TypeRef
            }
            isDeprecated
            deprecationReason
          }
          inputFields {
            ...InputValue
          }
          interfaces {
            ...TypeRef
          }
          enumValues(includeDeprecated: true) {
            name
            description
            isDeprecated
            deprecationReason
          }
          possibleTypes {
            ...TypeRef
          }
        }
        fragment InputValue on __InputValue {
          name
          description
          type { ...TypeRef }
          defaultValue
        }
        fragment TypeRef on __Type {
          kind
          name
          ofType {
            kind
            name
            ofType {
              kind
              name
              ofType {
                kind
                name
                ofType {
                  kind
                  name
                  ofType {
                    kind
                    name
                    ofType {
                      kind
                      name
                    }
                  }
                }
              }
            }
          }
        }
        """
    }
    headers = {
        "Content-Type": "application/json"
    }
    try:
        response = requests.post(url, json=introspection_query, headers=headers, timeout=TIMEOUT)
    except requests.RequestException as e:
        assert False, f"Request to {url} failed: {e}"

    assert response.status_code == 200, f"Expected status code 200 but got {response.status_code}"

    try:
        data = response.json()
    except ValueError:
        assert False, "Response is not valid JSON"

    # Validate that the response contains 'data' with '__schema'
    assert "data" in data, "'data' field not in GraphQL response"
    assert "__schema" in data["data"], "'__schema' field not in GraphQL response data"

    # Basic sanity checks for schema content
    schema = data["data"]["__schema"]
    assert "queryType" in schema and schema["queryType"] is not None, "'queryType' missing or null in schema"
    # mutationType and subscriptionType can be None depending on schema, so no strict assertion here

test_post_graphql_returns_valid_graphql_response()
